-- Secondary indexes not owned by PRIMARY KEY or UNIQUE constraints.
-- No production data is included.

CREATE INDEX copy_assets_type_active_updated_idx ON public.copy_laboratory_assets USING btree (asset_type, is_active, updated_at DESC);
CREATE INDEX copy_assignments_journey_idx ON public.copy_experiment_assignments USING btree (journey_id);
