CREATE INDEX email_suppressions_lookup_idx ON public.email_suppressions USING btree (normalized_email, active, platform);
CREATE INDEX email_unsubscribe_tokens_email_idx ON public.email_unsubscribe_tokens USING btree (normalized_email, platform);
CREATE INDEX email_unsubscribe_tokens_valid_idx ON public.email_unsubscribe_tokens USING btree (token, expires_at) WHERE (used_at IS NULL);
CREATE INDEX hotmart_delivery_logs_journey_idx ON public.hotmart_delivery_logs USING btree (journey_id);
CREATE INDEX hotmart_delivery_logs_retry_idx ON public.hotmart_delivery_logs USING btree (next_retry_at, id) WHERE ((status = 'FAILED'::text) AND (attempt_count < 3));
CREATE INDEX idx_purchase_journeys_email ON public.purchase_journeys USING btree (buyer_email);
CREATE INDEX idx_purchase_journeys_recovery ON public.purchase_journeys USING btree (recovery_allowed);
CREATE INDEX idx_purchase_journeys_status ON public.purchase_journeys USING btree (current_status);
CREATE INDEX idx_purchase_journeys_transaction ON public.purchase_journeys USING btree (transaction_id);
CREATE INDEX perfectpay_conversions_email_log_id_idx ON public.perfectpay_conversions USING btree (email_log_id) WHERE (email_log_id IS NOT NULL);
CREATE INDEX perfectpay_conversions_journey_id_idx ON public.perfectpay_conversions USING btree (journey_id);
CREATE INDEX perfectpay_delivery_logs_journey_idx ON public.perfectpay_delivery_logs USING btree (journey_id);
CREATE INDEX perfectpay_delivery_logs_retry_idx ON public.perfectpay_delivery_logs USING btree (next_retry_at, id) WHERE ((status = 'FAILED'::text) AND (attempt_count < 3));
CREATE INDEX perfectpay_email_clicks_email_log_id_clicked_at_idx ON public.perfectpay_email_clicks USING btree (email_log_id, clicked_at DESC);
CREATE INDEX perfectpay_email_logs_copy_experiment_idx ON public.perfectpay_email_logs USING btree (copy_experiment_id, sent_at DESC);
CREATE INDEX perfectpay_email_logs_copy_variant_idx ON public.perfectpay_email_logs USING btree (copy_variant_id, sent_at DESC);
CREATE INDEX perfectpay_email_logs_journey_id_idx ON public.perfectpay_email_logs USING btree (journey_id);
CREATE INDEX perfectpay_email_logs_retry_idx ON public.perfectpay_email_logs USING btree (next_retry_at, id) WHERE ((status = 'FAILED'::text) AND (attempt_count < 3));
CREATE INDEX perfectpay_email_logs_status_created_at_idx ON public.perfectpay_email_logs USING btree (status, created_at DESC);
CREATE INDEX perfectpay_events_customer_email_event_at_idx ON public.perfectpay_events USING btree (customer_email, event_at DESC);
CREATE INDEX perfectpay_events_sale_code_event_at_idx ON public.perfectpay_events USING btree (sale_code, event_at DESC);
CREATE INDEX perfectpay_events_unprocessed_idx ON public.perfectpay_events USING btree (created_at) WHERE (processed = false);
CREATE INDEX perfectpay_journeys_customer_email_updated_at_idx ON public.perfectpay_journeys USING btree (customer_email, updated_at DESC);
CREATE INDEX perfectpay_journeys_due_idx ON public.perfectpay_journeys USING btree (next_step_at, id) WHERE ((recovery_allowed = true) AND (recovered = false) AND (last_step_sent < 3));
CREATE INDEX recovery_conversions_converted_at_idx ON public.recovery_conversions USING btree (converted_at DESC);
CREATE INDEX recovery_conversions_email_log_idx ON public.recovery_conversions USING btree (email_log_id);
