CREATE INDEX recovery_email_clicks_email_log_clicked_idx ON public.recovery_email_clicks USING btree (email_log_id, clicked_at DESC);
CREATE INDEX recovery_email_clicks_journey_clicked_idx ON public.recovery_email_clicks USING btree (journey_id, clicked_at DESC);
