CREATE INDEX recovery_email_logs_copy_experiment_idx ON public.recovery_email_logs USING btree (copy_experiment_id);
CREATE INDEX recovery_email_logs_copy_variant_idx ON public.recovery_email_logs USING btree (copy_variant_id, sent_at DESC);
CREATE UNIQUE INDEX copy_assets_one_analysis_per_source_version ON public.copy_laboratory_assets USING btree (source_asset_id, source_updated_at) WHERE ((asset_type = 'research_note'::text) AND (source_asset_id IS NOT NULL) AND (source_updated_at IS NOT NULL));
CREATE UNIQUE INDEX copy_experiment_assignments_perfectpay_email_log_id_key ON public.copy_experiment_assignments USING btree (perfectpay_email_log_id) WHERE (perfectpay_email_log_id IS NOT NULL);
CREATE UNIQUE INDEX copy_experiments_one_open_per_slot ON public.copy_experiments USING btree (platform, recovery_flow, step) WHERE (status = ANY (ARRAY['shadow'::text, 'manual_review'::text, 'ready'::text, 'running'::text, 'paused'::text]));
CREATE UNIQUE INDEX copy_variants_one_active_champion ON public.copy_variants USING btree (platform, recovery_flow, step) WHERE ((role = 'champion'::text) AND (archived_at IS NULL));
CREATE UNIQUE INDEX copy_variants_platform_slot_version_key ON public.copy_variants USING btree (platform, recovery_flow, step, version_number);
CREATE UNIQUE INDEX email_suppressions_email_platform_uq ON public.email_suppressions USING btree (normalized_email, platform);
CREATE UNIQUE INDEX perfectpay_journeys_sale_code_uidx ON public.perfectpay_journeys USING btree (sale_code) WHERE ((sale_code IS NOT NULL) AND (sale_code <> ''::text));
CREATE UNIQUE INDEX recovery_email_logs_tracking_token_uidx ON public.recovery_email_logs USING btree (tracking_token);
CREATE UNIQUE INDEX uq_purchase_journeys_transaction ON public.purchase_journeys USING btree (transaction_id) WHERE (transaction_id IS NOT NULL);
